package com.example.starter.firmware.domain;

import java.util.Set;

/**
 * 固件版本兼容声明：型号集合、最低内存与必需能力标签。
 *
 * @param id           固件版本ID
 * @param name         版本名，全局唯一
 * @param models       兼容型号集合，至少一个
 * @param minMemoryMb  最低内存要求，单位MB，取值>=0
 * @param requiredTags 必需能力标签，空集合表示无要求
 */
public record FirmwareVersion(long id, String name, Set<String> models, int minMemoryMb,
                              Set<String> requiredTags) {
}

package com.example.starter.firmware.domain;

import java.util.Set;

/**
 * 设备硬件画像。型号、内存、能力标签均可为 null，表示缺少该画像字段，
 * 投放筛选时按不兼容处理并给出原因。更新只影响后续新任务，不追改已下发任务。
 *
 * @param deviceId       设备ID，对应 device 表
 * @param model          画像型号，null 表示缺少该字段
 * @param memoryMb       画像内存，单位MB，null 表示缺少该字段
 * @param tags           能力标签集合，null 表示缺少该字段
 * @param profileVersion 画像版本，从1开始，每次更新加一；任务只引用一个完整画像版本
 */
public record DeviceProfile(String deviceId, String model, Integer memoryMb, Set<String> tags,
                            int profileVersion) {
}

package com.example.starter.firmware.domain;

/**
 * 硬件画像投放单：一次按设备当次冻结画像筛选目标的发布动作。
 *
 * @param id        投放单ID
 * @param requestId 投放请求ID，全局唯一；同键重放首次目标清单，异参返回409
 * @param versionId 发布人选择的固件版本ID
 */
public record ProfileLaunch(long id, String requestId, long versionId) {
}

package com.example.starter.firmware.domain;

/**
 * 画像投放任务，仅为兼容设备创建；同设备同投放单最多一条。
 *
 * @param id             任务ID
 * @param launchId       所属投放单ID
 * @param deviceId       设备ID
 * @param profileVersion 筛选时冻结的画像版本，供失败率审计，下发后不可改
 * @param status         任务状态：PENDING 待回执，SUCCESS 成功，FAILED 失败
 * @param firstResult    首次回执结果（SUCCESS/FAILED），未回执为 null
 */
public record ProfileTask(long id, long launchId, String deviceId, int profileVersion,
                          TaskStatus status, ReceiptResult firstResult) {
}

package com.example.starter.firmware.domain;

/**
 * 投放排除记录：不兼容设备及原因，不计入失败率。
 *
 * @param id             排除记录ID
 * @param launchId       所属投放单ID
 * @param deviceId       设备ID
 * @param profileVersion 评估时画像版本，设备无画像为 null
 * @param reason         排除原因（无画像、缺字段、型号不匹配、内存不足、缺必需标签）
 */
public record ProfileExclusion(long id, long launchId, String deviceId, Integer profileVersion,
                               String reason) {
}

