package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.FirmwareVersion;
import com.example.starter.firmware.domain.ProfileCompatibility;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.sql.PreparedStatement;
import java.util.Optional;
import java.util.Set;

/**
 * 固件版本兼容声明数据访问。版本名全局唯一。
 */
@Repository
public class FirmwareVersionRepository {

    private static final RowMapper<FirmwareVersion> MAPPER = (rs, rowNum) -> new FirmwareVersion(
            rs.getLong("id"), rs.getString("name"),
            ProfileCompatibility.split(rs.getString("models")),
            rs.getInt("min_memory_mb"),
            ProfileCompatibility.split(rs.getString("required_tags")));

    private static final String COLUMNS = "id, name, models, min_memory_mb, required_tags";

    private final JdbcTemplate jdbc;

    public FirmwareVersionRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public long insert(String name, Set<String> models, int minMemoryMb, Set<String> requiredTags) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO firmware_version (name, models, min_memory_mb, required_tags)"
                            + " VALUES (?, ?, ?, ?)",
                    new String[]{"id"});
            ps.setString(1, name);
            ps.setString(2, ProfileCompatibility.join(models));
            ps.setInt(3, minMemoryMb);
            ps.setString(4, ProfileCompatibility.join(requiredTags));
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    public Optional<FirmwareVersion> findById(long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM firmware_version WHERE id = ?", MAPPER, id)
                .stream().findFirst();
    }
}

package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.DeviceProfile;
import com.example.starter.firmware.domain.ProfileCompatibility;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;
import java.util.Set;

/**
 * 设备硬件画像数据访问。画像版本每次更新加一；投放筛选时按 device_id 升序加行锁，
 * 与画像更新形成一致提交顺序，保证每个任务只引用一个完整画像版本。
 */
@Repository
public class DeviceProfileRepository {

    private static final RowMapper<DeviceProfile> MAPPER = (rs, rowNum) -> {
        String tags = rs.getString("tags");
        return new DeviceProfile(rs.getString("device_id"), rs.getString("model"),
                (Integer) rs.getObject("memory_mb"),
                tags == null ? null : ProfileCompatibility.split(tags),
                rs.getInt("profile_version"));
    };

    private static final String COLUMNS = "device_id, model, memory_mb, tags, profile_version";

    private final JdbcTemplate jdbc;

    public DeviceProfileRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(String deviceId, String model, Integer memoryMb, Set<String> tags) {
        jdbc.update("INSERT INTO device_profile (device_id, model, memory_mb, tags, profile_version)"
                        + " VALUES (?, ?, ?, ?, 1)",
                deviceId, model, memoryMb, tags == null ? null : ProfileCompatibility.join(tags));
    }

    /**
     * 更新画像字段并将画像版本加一，返回影响行数（0 表示画像不存在）。
     */
    public int update(String deviceId, String model, Integer memoryMb, Set<String> tags) {
        return jdbc.update("UPDATE device_profile SET model = ?, memory_mb = ?, tags = ?,"
                        + " profile_version = profile_version + 1, updated_at = CURRENT_TIMESTAMP"
                        + " WHERE device_id = ?",
                model, memoryMb, tags == null ? null : ProfileCompatibility.join(tags), deviceId);
    }

    public Optional<DeviceProfile> findById(String deviceId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM device_profile WHERE device_id = ?",
                MAPPER, deviceId).stream().findFirst();
    }

    /**
     * 按 device_id 升序加行锁读取全部画像，供投放筛选在同一事务内冻结画像版本。
     */
    public List<DeviceProfile> findAllForUpdate() {
        return jdbc.query("SELECT " + COLUMNS + " FROM device_profile ORDER BY device_id FOR UPDATE",
                MAPPER);
    }
}

package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.ProfileLaunch;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.sql.PreparedStatement;
import java.util.Optional;

/**
 * 画像投放单数据访问。request_id 全局唯一，同键重放首次目标清单。
 */
@Repository
public class ProfileLaunchRepository {

    private final JdbcTemplate jdbc;

    public ProfileLaunchRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public long insert(String requestId, long versionId) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO profile_launch (request_id, version_id) VALUES (?, ?)",
                    new String[]{"id"});
            ps.setString(1, requestId);
            ps.setLong(2, versionId);
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    public Optional<ProfileLaunch> findById(long id) {
        return jdbc.query("SELECT id, request_id, version_id FROM profile_launch WHERE id = ?",
                (rs, rowNum) -> new ProfileLaunch(rs.getLong("id"), rs.getString("request_id"),
                        rs.getLong("version_id")),
                id).stream().findFirst();
    }
}

package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.ProfileTask;
import com.example.starter.firmware.domain.ReceiptResult;
import com.example.starter.firmware.domain.TaskStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.sql.PreparedStatement;
import java.util.List;
import java.util.Optional;

/**
 * 画像投放任务数据访问。同设备同投放单由唯一约束 uk_ptask_launch_device 保证最多一条。
 */
@Repository
public class ProfileTaskRepository {

    private static final RowMapper<ProfileTask> MAPPER = (rs, rowNum) -> {
        String firstResult = rs.getString("first_result");
        return new ProfileTask(rs.getLong("id"), rs.getLong("launch_id"), rs.getString("device_id"),
                rs.getInt("profile_version"), TaskStatus.valueOf(rs.getString("status")),
                firstResult == null ? null : ReceiptResult.valueOf(firstResult));
    };

    private static final String COLUMNS = "id, launch_id, device_id, profile_version, status, first_result";

    private final JdbcTemplate jdbc;

    public ProfileTaskRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public long insert(long launchId, String deviceId, int profileVersion) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO profile_task (launch_id, device_id, profile_version, status)"
                            + " VALUES (?, ?, ?, 'PENDING')",
                    new String[]{"id"});
            ps.setLong(1, launchId);
            ps.setString(2, deviceId);
            ps.setInt(3, profileVersion);
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    public Optional<ProfileTask> findById(long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM profile_task WHERE id = ?", MAPPER, id)
                .stream().findFirst();
    }

    public Optional<ProfileTask> findByIdForUpdate(long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM profile_task WHERE id = ? FOR UPDATE", MAPPER, id)
                .stream().findFirst();
    }

    public List<ProfileTask> findByLaunch(long launchId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM profile_task WHERE launch_id = ? ORDER BY id",
                MAPPER, launchId);
    }

    public List<ProfileTask> findByDevice(String deviceId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM profile_task WHERE device_id = ? ORDER BY id",
                MAPPER, deviceId);
    }

    public void complete(long id, ReceiptResult result) {
        jdbc.update("UPDATE profile_task SET status = ?, first_result = ?, updated_at = CURRENT_TIMESTAMP"
                + " WHERE id = ?", result.name(), result.name(), id);
    }

    public long countByLaunchAndStatus(long launchId, TaskStatus status) {
        Long count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM profile_task WHERE launch_id = ? AND status = ?",
                Long.class, launchId, status.name());
        return count == null ? 0 : count;
    }
}

package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.ProfileExclusion;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * 投放排除记录数据访问。不兼容设备只记录原因，不创建任务、不计入失败率。
 */
@Repository
public class ProfileExclusionRepository {

    private static final RowMapper<ProfileExclusion> MAPPER = (rs, rowNum) -> new ProfileExclusion(
            rs.getLong("id"), rs.getLong("launch_id"), rs.getString("device_id"),
            (Integer) rs.getObject("profile_version"), rs.getString("reason"));

    private static final String COLUMNS = "id, launch_id, device_id, profile_version, reason";

    private final JdbcTemplate jdbc;

    public ProfileExclusionRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(long launchId, String deviceId, Integer profileVersion, String reason) {
        jdbc.update("INSERT INTO profile_exclusion (launch_id, device_id, profile_version, reason)"
                + " VALUES (?, ?, ?, ?)", launchId, deviceId, profileVersion, reason);
    }

    public List<ProfileExclusion> findByLaunch(long launchId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM profile_exclusion WHERE launch_id = ?"
                + " ORDER BY id", MAPPER, launchId);
    }

    public long countByLaunch(long launchId) {
        Long count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM profile_exclusion WHERE launch_id = ?", Long.class, launchId);
        return count == null ? 0 : count;
    }
}

